package io.github.turbopro.ism.bootstrap;
import com.fasterxml.jackson.databind.JsonNode;
import io.github.turbopro.ism.platform.packageplan.*;
import org.junit.jupiter.api.Test;
import org.springframework.http.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;
class SubscriptionAssignmentIT extends SupplierQuotaSupport {
    String version(Fixture f,int no,long n){long p=jdbc.queryForObject("SELECT package_id FROM plt_package_version v JOIN plt_tenant t ON t.package_version_id=v.id WHERE t.id=?",Long.class,f.tenant());var v=plans.createVersion(p,new PackagePlanModels.CreateVersion(no,"分配版本"+no,null,List.of(new PackagePlanModels.ModuleGrant("SUPPLIER",true,Map.of("SUPPLIER_COUNT",n)))));plans.publish(Long.parseLong(v.id()),0,790001);return v.id();}
    JsonNode preview(Fixture f,String target,String t){return ok(request("POST","/api/console/tenants/"+f.tenant()+"/subscription-preview?packageVersionId="+target,t,null,null));}
    Map<String,Object> body(String id,JsonNode p,boolean future){var b=new HashMap<String,Object>();b.put("packageVersionId",id);b.put("tenantVersion",p.path("tenantVersion").asInt());b.put("activationMode",future?"SCHEDULED":"IMMEDIATE");b.put("effectiveFrom",future?LocalDateTime.now(ZoneOffset.UTC).plusDays(1).toString():p.path("asOf").asText());b.put("exceptions",Map.of());return b;}
    ResponseEntity<JsonNode> assign(Fixture f,String t,String k,Map<String,Object> b){return request("POST","/api/console/tenants/"+f.tenant()+"/subscription",t,k,b);}
    @Test void previewImmediateAndFutureReplacementHaveCurrentVersionAndDurableHistory(){var f=fixture();String t=login(true),id=version(f,2,10);var p=preview(f,id,t);assertThat(p.path("replacedFuturePlans").asInt()).isZero();ok(assign(f,t,"assign-immediate-"+f.tenant(),body(id,p,false)));assertThat(usage(f).path("limit").asInt()).isEqualTo(10);var p2=preview(f,id,t);assertThat(p2.path("tenantVersion").asInt()).isEqualTo(p.path("tenantVersion").asInt()+1);ok(assign(f,t,"assign-future-"+f.tenant(),body(id,p2,true)));assertThat(preview(f,id,t).path("replacedFuturePlans").asInt()).isOne();var p3=preview(f,id,t);ok(assign(f,t,"replace-future-"+f.tenant(),body(id,p3,true)));assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM plt_subscription WHERE tenant_id=? AND status='TERMINATED'",Integer.class,f.tenant())).isOne();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM plt_subscription WHERE tenant_id=? AND status='ACTIVE' AND effective_from>UTC_TIMESTAMP(3)",Integer.class,f.tenant())).isOne();}
    @Test void optimisticCompetitionHasOneWinnerAndSameKeyReplays(){var f=fixture();String t=login(true),id=version(f,2,10);var b=body(id,preview(f,id,t),false);String k="replay-"+f.tenant();var first=ok(assign(f,t,k,b));assertThat(ok(assign(f,t,k,b))).isEqualTo(first);assertThat(assign(f,t,"stale-"+f.tenant(),b).getStatusCode()).isEqualTo(HttpStatus.CONFLICT);b.put("effectiveTo",LocalDateTime.now(ZoneOffset.UTC).plusDays(1).toString());assertThat(assign(f,t,k,b).getStatusCode()).isEqualTo(HttpStatus.CONFLICT);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM sys_audit_event WHERE object_id=? AND action='SUBSCRIPTION_ASSIGN'",Integer.class,f.tenant())).isOne();}
    @Test void simultaneousDistinctRequestsCannotReplaceEachOtherFromOnePreview()throws Exception{var f=fixture();String t=login(true),id=version(f,2,10);var b=body(id,preview(f,id,t),true);var gate=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->{gate.await();return assign(f,t,"race-a-"+f.tenant(),b).getStatusCode().value();});var c=pool.submit(()->{gate.await();return assign(f,t,"race-b-"+f.tenant(),b).getStatusCode().value();});gate.countDown();assertThat(List.of(a.get(30,TimeUnit.SECONDS),c.get(30,TimeUnit.SECONDS))).containsExactlyInAnyOrder(200,409);}finally{pool.shutdownNow();}}
    @Test void expiredScheduleMissingFieldsInvalidDatesAndRetiredParentRejectWithoutWrites(){var f=fixture();String t=login(true),id=version(f,2,10);var p=preview(f,id,t);long before=count("plt_subscription",f.tenant());for(String field:List.of("tenantVersion","activationMode")){var b=body(id,p,false);b.remove(field);assertThat(assign(f,t,UUID.randomUUID().toString(),b).getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);}var b=body(id,p,true);b.put("effectiveFrom",p.path("asOf").asText());assertThat(assign(f,t,"late-"+f.tenant(),b).getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);b.put("effectiveFrom","99999-01-01T00:00:00");assertThat(assign(f,t,"bad-year-"+f.tenant(),b).getStatusCode().value()).isIn(400,422);jdbc.update("UPDATE plt_package p JOIN plt_package_version v ON v.package_id=p.id SET p.status='OFFLINE' WHERE v.id=?",id);assertThat(assign(f,t,"offline-"+f.tenant(),body(id,p,false)).getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);assertThat(count("plt_subscription",f.tenant())).isEqualTo(before);}
    @Test void actualUsageChangedSincePreviewIsRecheckedAtSave(){var f=fixture();limit(f,10);String t=login(true),id=version(f,2,1);var p=preview(f,id,t);assertThat(p.path("quotaChanges").path("SUPPLIER_COUNT").path("exceedsTarget").asBoolean()).isFalse();String user=tenantLogin(f,"pref-admin");ok(create(f,user,"SINCE-A"));ok(create(f,user,"SINCE-B"));assertThat(assign(f,t,"usage-"+f.tenant(),body(id,p,false)).getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);assertThat(usage(f).path("limit").asLong()).isEqualTo(10);}
    @Test void auditFailureRollsBackAndOriginalRequestRecoversAndReadonlyCannotReplay()throws Exception{var f=fixture();String t=login(true),id=version(f,2,10);var b=body(id,preview(f,id,t),false);String k="audit-"+f.tenant();int before=count("plt_subscription",f.tenant());trigger("CREATE TRIGGER sa_audit_fail BEFORE INSERT ON sys_audit_event FOR EACH ROW BEGIN IF NEW.action='SUBSCRIPTION_ASSIGN' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='test assignment audit failure'; END IF; END");try{assertThat(assign(f,t,k,b).getStatusCode()).isEqualTo(HttpStatus.INTERNAL_SERVER_ERROR);}finally{trigger("DROP TRIGGER sa_audit_fail");}assertThat(count("plt_subscription",f.tenant())).isEqualTo(before);ok(assign(f,t,k,b));assertThat(assign(f,login(false),k,b).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);}
    @Test void cancelledTenantCannotReceiveAnAssignment(){var f=fixture();String t=login(true),id=version(f,2,10);var b=body(id,preview(f,id,t),false);jdbc.update("UPDATE plt_tenant SET status='CANCELLED' WHERE id=?",f.tenant());assertThat(assign(f,t,"cancelled-"+f.tenant(),b).getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);}
}
